(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('low');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    __rhf.god(true);
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    g.state.money = 2000;
    g.state.gear.camera = true;
    g.photo.wipe();
    g.screens.open('shop', { tab: 'jobs' });
    const offers = g.jobs.offers().map((j) => j.id);
    return 'job board offers: ' + offers.join(', ') + ' | tabs: ' + document.getElementById('sheet-tabs').textContent;
  })()

(() => {
    const g = __rhf.game;
    g.state.job = null;
    g.jobs.take('bigfoot');
    g.screens.render();
    return 'job: ' + JSON.stringify(g.state.job) + ', ready ' + g.jobs.ready();
  })()

(() => {
    const g = __rhf.game;
    g.screens.close();
    // dusk in the forest near Salmon Bend
    g.env.setTime(20.8);
    const W = g.world;
    const b = W.place('bend');
    // a meadow by the forest, the way you would look for it
    let spot = null;
    const fo = (x, z) => W.forest[W.cellIndex(x, z)];
    for (let k = 0; k < 8000 && !spot; k++) {
      const x = b.x + (Math.random() - 0.5) * 500;
      const z = b.z + (Math.random() - 0.5) * 500;
      if (!W.inBounds(x, z, 80) || W.waterAt(x, z) || W.slopeAt(x, z) > 0.2 || fo(x, z) > 30) continue;
      let near = false;
      for (let a = 0; a < 12 && !near; a++) near = fo(x + Math.cos(a) * 100, z + Math.sin(a) * 100) >= 100;
      if (near) spot = { x, z };
    }
    if (!spot) return 'no forest spot';
    g.player.place(spot.x, spot.z, 0);
    g.player.tool = 'camera';
    g.viewmodel.setTool('none');
    // it only shows itself where nothing hides it: look around until it does
    let ok = false;
    for (let k = 0; k < 24 && !ok; k++) {
      g.player.yaw = k * 0.6;
      ok = g.bigfoot.spawn();
    }
    return 'spawned ' + ok + ' at ' + g.bigfoot.pos.x.toFixed(0) + ',' + g.bigfoot.pos.z.toFixed(0) + ', ' + Math.hypot(g.bigfoot.pos.x - spot.x, g.bigfoot.pos.z - spot.z).toFixed(0) + ' m away';
  })()

(async () => {
    const g = __rhf.game;
    const B = g.bigfoot;
    const P = g.player;
    // aim at it through the 8x lens
    while (g.photo.zoom !== 8) {
      g.photo.zoomIndex = (g.photo.zoomIndex + 1) % 4;
    }
    const aim = () => {
      const dx = B.pos.x - P.pos.x;
      const dz = B.pos.z - P.pos.z;
      P.yaw = Math.atan2(-dx, -dz);
      P.pitch = Math.atan2(B.pos.y + 1.4 - (P.pos.y + 1.7), Math.hypot(dx, dz));
    };
    aim();
    const t0 = g.time;
    await __until(() => {
      aim();
      return g.time - t0 > 1.5;
    }, 120000);
    aim();
    const f = g.photo.evaluate();
    return 'through the lens: ' + (f ? f.id + ' ' + f.stars + ' stars, fills ' + (f.frac * 100).toFixed(0) + '%' : 'nothing');
  })()

(async () => {
    const g = __rhf.game;
    __rhf.press('primary');
    await __until(() => g.photo.album.shots.bigfoot, 120000);
    const p = g.photo.album.shots.bigfoot;
    return 'album bigfoot: ' + (p ? p.stars + ' stars' : 'NO') + ', job done ' + !!(g.state.job && g.state.job.done) + ', ready ' + g.jobs.ready();
  })()

(() => {
    const g = __rhf.game;
    const before = g.state.money;
    g.jobs.turnIn();
    return 'turned in: money ' + before + ' > ' + g.state.money + ', jobs done ' + JSON.stringify(g.state.jobsDone) + ', job ' + g.state.job;
  })()

(() => {
    const g = __rhf.game;
    g.jobs.drop();
    g.jobs.take('cannery');
    const fish = (w) => ({ species: 'sockeye', weight: w, length: 60, value: 40, legend: null, name: 'Sockeye Salmon', lure: 'spinner' });
    g.state.cooler = [fish(3), { species: 'pink', weight: 2, length: 50, value: 10, legend: null, name: 'Pink Salmon', lure: 'spinner' }, fish(4)];
    const r1 = 'two sockeye: ready ' + g.jobs.ready();
    g.state.cooler.push(fish(5));
    const r2 = 'three: ready ' + g.jobs.ready();
    g.jobs.turnIn();
    return r1 + '; ' + r2 + '; after turning in the cooler holds ' + g.state.cooler.map((f) => f.species).join(', ');
  })()

(() => {
    const g = __rhf.game;
    g.screens.open('journal', { tab: 'photos' });
    return 'album open';
  })()
